TESTS_FIXTURES_DIR = os.path.join(os.path.dirname(__file__), "..", "tests", "fixtures")

# Score-gap cutoffs (from the leader) evaluated by the ground-truth ranking
# diagnostic below — answers "would a Powell joint-refine pass limited to
# candidates within epsilon of the leader actually reach the true candidate,"
# before any such pass gets written (see docs/pipeline-tuning.md's Item 3
# investigation and the plan this script supports).
GROUND_TRUTH_EPSILONS = (0.02, 0.05, 0.10, 0.15)
GROUND_TRUTH_TOP_KS = (1, 2, 3, 5)


def _ground_truth_rank_info(traced_result, traces, true_family: str, true_weight: int) -> dict | None:
    """Where does the known-correct candidate land in today's full-search
    ranking? None if the true (family, weight) isn't in FONT_REGISTRY (all
    ground truth above is drawn from registry fonts, so this shouldn't
    happen in practice — guarded rather than assumed).
    """
    ranked = sorted(
        ((t.family, t.weight, max(t.restart_scores)) for t in traces),
        key=lambda r: r[2],
        reverse=True,
    )
    true_index = next((i for i, r in enumerate(ranked) if r[0] == true_family and r[1] == true_weight), None)
    if true_index is None:
        return None
    leader_score = ranked[0][2]
    true_score = ranked[true_index][2]
    return {
        "true_family": true_family,
        "true_weight": true_weight,
        "true_rank": true_index + 1,  # 1-indexed, so rank 1 == leader
        "true_score": true_score,
        "leader_family": ranked[0][0],
        "leader_weight": ranked[0][1],
        "leader_score": leader_score,
        "gap_from_leader": leader_score - true_score,
        "within_top_k": {k: true_index < k for k in GROUND_TRUTH_TOP_KS},
        "within_epsilon": {eps: (leader_score - true_score) <= eps for eps in GROUND_TRUTH_EPSILONS},
    }


def analyze_fixture(path: str) -> list[dict]:
    image = Image.open(path).convert("RGB")
    image_bgr = np.array(image)[:, :, ::-1].copy()
    detect_result = detect(image_bgr)
    fixture_name = os.path.basename(path)

    region_records = []
    for line in detect_result.lines:
        if not line.text.strip():
            continue

        separation = separate(image_bgr, line.bbox)

        # Verification: production's real match_font vs our traced copy must
        # produce bit-identical results, or the trace isn't trustworthy.
        COUNTERS.reset()
        t0 = time.perf_counter()
        real_result = match_font_production(line.text, separation.alpha, separation.alpha.shape, line.bbox[3])
        real_cpu_s = time.perf_counter() - t0

        COUNTERS.reset()
        t0 = time.perf_counter()
        traced_result, traces = match_font_traced(line.text, separation.alpha, separation.alpha.shape, line.bbox[3])
        traced_cpu_s = time.perf_counter() - t0

        identical = (
            real_result.family == traced_result.family
            and real_result.weight == traced_result.weight
            and abs(real_result.size - traced_result.size) < 1e-9
            and abs(real_result.letter_spacing - traced_result.letter_spacing) < 1e-9
            and abs(real_result.baseline_y - traced_result.baseline_y) < 1e-9
            and abs(real_result.x_offset - traced_result.x_offset) < 1e-9
            and abs(real_result.score - traced_result.score) < 1e-9
        )

        # Simulate "restart #1 only" (zero extra evaluations — pure
        # re-aggregation of data already computed above).
        restart1_only_scores = [(t.family, t.weight, t.restart_scores[0], t.restart_results[0]) for t in traces]
        restart1_winner = max(restart1_only_scores, key=lambda r: r[2])
        both_restarts_winner = (traced_result.family, traced_result.weight, traced_result.score)

        restart2_ever_better = any(len(t.restart_scores) > 1 and t.restart_scores[1] > t.restart_scores[0] for t in traces)
        restart2_changes_this_candidate_winner = [
            t.chosen_restart_index == 1 for t in traces
        ]
        restart2_changes_overall_winner = (restart1_winner[0], restart1_winner[1]) != (
            both_restarts_winner[0], both_restarts_winner[1]
        )
        # Does restart #1-only reproduce the EXACT final params (not just family/weight)?
        restart1_winner_params = restart1_winner[3]
        restart1_reproduces_exact = (
            not restart2_changes_overall_winner
            and abs(restart1_winner_params[0] - traced_result.size) < 1e-9
            and abs(restart1_winner_params[1] - traced_result.letter_spacing) < 1e-9
            and abs(restart1_winner_params[2] - traced_result.baseline_y) < 1e-9
            and abs(restart1_winner_params[3] - traced_result.x_offset) < 1e-9
        )

        # Coarse-grid ranking vs final ranking: would the coarse score alone
        # (restart 1's step-1 result, before any refine) pick the same winner?
        coarse_only = [(t.family, t.weight, t.coarse_best_scores[0]) for t in traces]
        coarse_winner = max(coarse_only, key=lambda r: r[2])
        coarse_predicts_final_winner = (coarse_winner[0], coarse_winner[1]) == (
            traced_result.family, traced_result.weight
        )

        # Runner-up: traced_result.top_candidates is sorted desc by score
        # (built the same way production's match_font builds it), so [1] is
        # the second-best candidate overall, [0] the winner. Zero extra
        # evaluations — reads data match_font_traced already computed.
        runner_up = traced_result.top_candidates[1] if len(traced_result.top_candidates) > 1 else None

        ground_truth = SYNTHETIC_GROUND_TRUTH.get((fixture_name, line.text))
        ground_truth_rank_info = (
            _ground_truth_rank_info(traced_result, traces, ground_truth[0], ground_truth[1])
            if ground_truth is not None
            else None
        )

        # Full-stage (separate/match/color/ui) timing, via the exact function
        # production /analyze uses per line — a faithful proxy for real
        # /analyze latency, not just match_font in isolation. Runs match_font
        # a third time for this line (on top of the production/traced calls
        # above); acceptable here since this is a one-off diagnostic script,
        # not a hot path.
        _, _, full_stage_timings, _ = _process_line(image_bgr, line, "diagnostic")

        region_records.append(
            {
                "fixture": fixture_name,
                "text": line.text,
                "region_h": line.bbox[3],
                "candidate_count": len(traces),
                "restart_count": len(traces[0].restart_scores) if traces else 0,
                "render_calls": COUNTERS.render_calls,
                "score_calls": COUNTERS.score_calls,
                "cache_hits": COUNTERS.cache_hits,
                "cache_misses": COUNTERS.cache_misses,
                "real_cpu_s": real_cpu_s,
                "traced_cpu_s": traced_cpu_s,
                "identical_to_production": identical,
                "final_family": traced_result.family,
                "final_weight": traced_result.weight,
                "final_score": traced_result.score,
                "runner_up_family": runner_up.family if runner_up else None,
                "runner_up_weight": runner_up.weight if runner_up else None,
                "runner_up_score": runner_up.score if runner_up else None,
                "margin": (traced_result.score - runner_up.score) if runner_up else None,
                "ground_truth_rank_info": ground_truth_rank_info,
                "full_stage_separate_s": full_stage_timings.separate_s,
                "full_stage_match_s": full_stage_timings.match_s,
                "full_stage_color_s": full_stage_timings.color_s,
                "full_stage_ui_s": full_stage_timings.ui_s,
                "restart2_ever_beats_restart1_for_some_candidate": restart2_ever_better,
                "restart2_changes_any_candidates_own_winner": any(restart2_changes_this_candidate_winner),
                "count_candidates_where_restart2_won": sum(restart2_changes_this_candidate_winner),
                "restart2_changes_overall_family_weight_winner": restart2_changes_overall_winner,
                "restart1_only_reproduces_exact_matchresult": restart1_reproduces_exact,
                "coarse_grid_predicts_final_winner": coarse_predicts_final_winner,
                "all_candidate_scores_both_restarts": [
                    {"family": t.family, "weight": t.weight, "restart_scores": t.restart_scores, "coarse_scores": t.coarse_best_scores}
                    for t in traces
                ],
            }
        )
    return region_records


def _print_summary(all_records: list[dict]) -> None:
    """Baseline numbers for the font-matching accuracy plan (registry size,
    per-region timing, and whether a top-K/epsilon Powell-refine pass could
    even work) — printed, not asserted, so this script stays a diagnostic,
    not a test.
    """
    from fonts.registry import FONT_REGISTRY

    print("\n=== SUMMARY ===", flush=True)
    print(f"registry_size={len(FONT_REGISTRY)}", flush=True)
    print(f"region_count={len(all_records)}", flush=True)

    match_times = [r["real_cpu_s"] for r in all_records]
    full_stage_times = [
        r["full_stage_separate_s"] + r["full_stage_match_s"] + r["full_stage_color_s"] + r["full_stage_ui_s"]
        for r in all_records
    ]
    if match_times:
        print(
            f"match_font_s: mean={statistics.mean(match_times):.4f} "
            f"median={statistics.median(match_times):.4f} max={max(match_times):.4f}",
            flush=True,
        )
    if full_stage_times:
        print(
            f"full_stage_s (separate+match+color+ui, one region): "
            f"mean={statistics.mean(full_stage_times):.4f} median={statistics.median(full_stage_times):.4f}",
            flush=True,
        )

    ground_truth_records = [r["ground_truth_rank_info"] for r in all_records if r["ground_truth_rank_info"]]
    print(f"\nground_truth_matched_regions={len(ground_truth_records)} (of {len(all_records)} total)", flush=True)
    if ground_truth_records:
        for k in GROUND_TRUTH_TOP_KS:
            hit_rate = sum(1 for g in ground_truth_records if g["within_top_k"][k]) / len(ground_truth_records)
            print(f"  within_top_{k}: {hit_rate:.1%}", flush=True)
        for eps in GROUND_TRUTH_EPSILONS:
            hit_rate = sum(1 for g in ground_truth_records if g["within_epsilon"][eps]) / len(ground_truth_records)
            print(f"  within_epsilon_{eps}: {hit_rate:.1%}", flush=True)
        misses = [g for g in ground_truth_records if g["true_rank"] > 1]
        print(f"  regions where the true candidate does NOT already win outright: {len(misses)}", flush=True)
        for g in misses:
            print(
                f"    true={g['true_family']}/{g['true_weight']} rank={g['true_rank']} "
                f"gap_from_leader={g['gap_from_leader']:.4f} "
                f"leader={g['leader_family']}/{g['leader_weight']}",
                flush=True,
            )


def main():
    all_records = []

    # Checked-in synthetic fixtures (tests/fixtures/) — always present,
    # the only source with known ground-truth family/weight (see
    # SYNTHETIC_GROUND_TRUTH above), so this is what answers the item-3
    # top-K/epsilon question.
    synthetic_paths = sorted(
        p for pattern in ("*.png", "*.jpg", "*.jpeg") for p in glob.glob(os.path.join(TESTS_FIXTURES_DIR, pattern))
    )
    print(f"=== synthetic fixtures with ground truth ({len(synthetic_paths)}) ===", flush=True)
    for path in synthetic_paths:
        recs = analyze_fixture(path)
        all_records.extend(recs)
        for r in recs:
            gt = r["ground_truth_rank_info"]
            gt_note = f"gt_rank={gt['true_rank']} gap={gt['gap_from_leader']:.3f}" if gt else "gt=n/a"
            print(
                f"  {r['fixture']:24s} {r['text']!r:30s} final={r['final_family']}/{r['final_weight']} "
                f"margin={r['margin']:.3f} {gt_note} "
                f"identical={r['identical_to_production']} coarse_predicts={r['coarse_grid_predicts_final_winner']}"
            )

    # Optional ad-hoc local investigation sources — not checked in, may not
    # exist on every machine, so skipped gracefully rather than required.
    real_image = "/fixtures/real_18region.jpg"
    if os.path.exists(real_image):
        print(f"\n=== real production image: {real_image} ===", flush=True)
        real_records = analyze_fixture(real_image)
        all_records.extend(real_records)
        for r in real_records:
            print(
                f"  {r['text']!r:40s} render={r['render_calls']:4d} score={r['score_calls']:4d} "
                f"hits={r['cache_hits']:3d} cpu={r['real_cpu_s']:.3f}s identical={r['identical_to_production']} "
                f"restart2_changes_overall={r['restart2_changes_overall_family_weight_winner']} "
                f"restart1_exact={r['restart1_only_reproduces_exact_matchresult']} "
                f"coarse_predicts={r['coarse_grid_predicts_final_winner']}"
            )
    else:
        print(f"\n(skipping {real_image} — not present on this machine)", flush=True)

    local_fixtures_dir = "/fixtures/local"
    local_paths = sorted(
        p for pattern in ("*.png", "*.jpg", "*.jpeg") for p in glob.glob(os.path.join(local_fixtures_dir, pattern))
    )
    if local_paths:
        print(f"\n=== local fixtures ({len(local_paths)}) ===", flush=True)
        for path in local_paths:
            recs = analyze_fixture(path)
            all_records.extend(recs)
            for r in recs:
                print(
                    f"  {r['fixture']:24s} {r['text']!r:30s} render={r['render_calls']:4d} "
                    f"identical={r['identical_to_production']} restart2_changes_overall={r['restart2_changes_overall_family_weight_winner']} "
                    f"restart1_exact={r['restart1_only_reproduces_exact_matchresult']} coarse_predicts={r['coarse_grid_predicts_final_winner']}"
                )
    else:
        print(f"\n(skipping {local_fixtures_dir} — not present on this machine)", flush=True)

    _print_summary(all_records)

    out_path = os.path.join(os.path.dirname(__file__), "match_investigation_results.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(all_records, f, indent=2)
    print(f"\nwrote {len(all_records)} region records to {out_path}")


if __name__ == "__main__":
    main()
